const rows = $input.all().map(item => item.json);

if (rows.length === 0) {
  return [];
}

const events = [];

function cleanLocalTimestamp(value) {
  if (!value) return '';
  return String(value).replace(/\D/g, '');
}

for (const r of rows) {
  const initialContentId = `${r.review_id}::INITIAL`;

  // 首评尚未进入 Canonical Layer
  if (!r.initial_exists) {
    events.push({
      source_staging_id: r.staging_id,
      collector_run_id: r.collector_run_id,

      platform: r.platform,
      shop_name: r.shop_name,

      product_id: r.item_id,
      product_name: r.item_name,
      sku_id: r.sku_id,
      sku_name: r.sku_name,

      source_review_id: r.review_id,

      content_id: initialContentId,
      content_type: 'INITIAL_REVIEW',

      root_review_id: initialContentId,
      parent_content_id: null,

      author_role: 'BUYER',
      author_id: r.buyer_id,

      product_rating: r.rating,
      rating_scale_max: 5,
      rating_label: r.rating_label,

      content_text: r.review_text,
      content_time: r.review_time_local,

      content_key:
        `${r.platform}::${r.shop_name}::${initialContentId}`
    });
  }

  // 新追评尚未进入 Canonical Layer
  if (
    r.append_review_text &&
    r.append_review_time_local &&
    !r.followup_exists
  ) {
    const followupContentId =
      `${r.review_id}::FOLLOWUP::${cleanLocalTimestamp(
        r.append_review_time_local
      )}`;

    events.push({
      source_staging_id: r.staging_id,
      collector_run_id: r.collector_run_id,

      platform: r.platform,
      shop_name: r.shop_name,

      product_id: r.item_id,
      product_name: r.item_name,
      sku_id: r.sku_id,
      sku_name: r.sku_name,

      source_review_id: r.review_id,

      content_id: followupContentId,
      content_type: 'FOLLOWUP_REVIEW',

      root_review_id: initialContentId,
      parent_content_id: initialContentId,

      author_role: 'BUYER',
      author_id: r.buyer_id,

      product_rating: r.rating,
      rating_scale_max: 5,
      rating_label: r.rating_label,

      content_text: r.append_review_text,
      content_time: r.append_review_time_local,

      content_key:
        `${r.platform}::${r.shop_name}::${followupContentId}`
    });
  }
}

return [
  {
    json: {
      collector_run_id: rows[0].collector_run_id,
      staging_count: rows.length,
      event_count: events.length,
      events
    }
  }
];

const result = $input.first().json;

if (!Array.isArray(result.events)) {
  throw new Error('events 不是数组');
}

return result.events.map(event => ({
  json: {
    ...event
  }
}));

const insertResults = $input.all();
const adapterResult = $('Build Canonical Events').first().json;

return [
  {
    json: {
      collector_run_id: adapterResult.collector_run_id,
      staging_count: adapterResult.staging_count,
      event_count: adapterResult.event_count,
      insert_output_count: insertResults.length
    }
  }
];
